SELECT rtks_skill.id, rtks_skill.resource_id, rtks_skill.system_id, rtks_skill.categary_id, rtks_skill.content, rtks_skill.courses, rtks_skill.create_time, rtks_skill.update_time, rtks_skill_categary.content categary, rtks_skill_system.content system FROM rtks_skill LEFT JOIN rtks_skill_categary ON rtks_skill.categary_id = rtks_skill_categary.resource_id LEFT JOIN rtks_skill_system ON rtks_skill.system_id = rtks_skill_system.resource_id
1=1
AND ( rtks_skill.resource_id LIKE #{pattern} OR rtks_skill.content LIKE #{pattern} )
AND rtks_skill.system_id = #{skillListReq.systemId}
AND rtks_skill.categary_id = #{skillListReq.categaryId}
